import{_ as t,o as h,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Luật Đảm bảo Giáo dục","description":"","frontmatter":{},"headers":[],"relativePath":"vi/43-教育保障法.md","filePath":"vi/43-教育保障法.md"}'),g={name:"vi/43-教育保障法.md"};function u(a,n,o,l,d,r){return h(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="luat-đam-bao-giao-duc" tabindex="-1">Luật Đảm bảo Giáo dục <a class="header-anchor" href="#luat-đam-bao-giao-duc" aria-label="Permalink to &quot;Luật Đảm bảo Giáo dục&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>43</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Quyền giáo dục, giáo dục cộng sinh, truyền承 tu luyện, học tập suốt đời, công bằng giáo dục</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Đảm bảo Giáo dục》 là một trong năm luật pháp hỗ trợ của văn minh cộng sinh neo, nhằm đảm bảo quyền được giáo dục của mọi sự sống bên trong Hengyuanzhou, xây dựng hệ thống giáo dục với khái niệm cốt lõi &quot;tiến hóa cộng sinh&quot;, và cung cấp sự hỗ trợ về tri thức và nhân tài cho sự tiến bộ chung của mọi tộc.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc công bằng giáo dục</td><td>Mọi sự sống, bất kể tộc, trình độ tu luyện, xuất thân, đều được hưởng cơ hội giáo dục bình đẳng</td></tr><tr><td>Nguyên tắc dạy học theo tài năng</td><td>Tôn trọng sự khác biệt về thiên tài và lựa chọn con đường tiến hóa của mỗi sự sống, cung cấp kế hoạch giáo dục được cá nhân hóa</td></tr><tr><td>Nguyên tắc nhất quán tri thức và hành động</td><td>Kết hợp tri thức lý luận và tu luyện thực tế, phản đối giáo dục hàn lâm trừu tượng tách rời thực tế</td></tr><tr><td>Nguyên tắc mở cửa và chia sẻ</td><td>Nguồn lực giáo dục mở cửa cho toàn xã hội, các pháp môn cơ bản của ba trăm hệ thống tu luyện nguồn gốc được truyền授 miễn phí</td></tr><tr><td>Nguyên tắc học tập suốt đời</td><td>Giáo dục xuyên suốt toàn bộ quá trình cuộc sống, hỗ trợ học tập liên tục và nâng cao năng lực ở mọi giai đoạn</td></tr><tr><td>Nguyên tắc đa dạng văn hóa</td><td>Tôn trọng truyền thống văn hóa của mỗi tộc, khuyến khích trao đổi và học hỏi lẫn nhau giữa các văn hóa</td></tr></tbody></table><h2 id="_2-đam-bao-phap-luat-ve-quyen-đuoc-giao-duc" tabindex="-1">2. Đảm bảo pháp luật về quyền được giáo dục <a class="header-anchor" href="#_2-đam-bao-phap-luat-ve-quyen-đuoc-giao-duc" aria-label="Permalink to &quot;2. Đảm bảo pháp luật về quyền được giáo dục&quot;">​</a></h2><p>Luật này quy định rõ ràng rằng quyền được giáo dục là quyền cơ bản được Hiến pháp Cộng sinh trao cho mỗi sự sống, và nhà nước cũng như văn minh có nghĩa vụ đảm bảo việc thực hiện quyền này:</p><ol><li><strong>Giáo dục cơ bản miễn phí</strong>: Mọi sự sống đều có quyền nhận giáo dục cơ bản miễn phí, bao gồm tri thức phổ thông, pháp môn tu luyện cơ bản, khái niệm văn minh cộng sinh, v.v., thời gian học là sáu đến mười hai năm, được điều chỉnh theo chu kỳ phát triển của tộc.</li><li><strong>Giới thiệu tu luyện miễn phí</strong>: Các pháp môn cơ bản của ba trăm hệ thống tu luyện nguồn gốc vũ trụ được mở cửa miễn phí cho mọi sự sống, không tổ chức hay cá nhân nào được tư nhân hóa các pháp môn tu luyện cơ bản và truyền授 với phí.</li><li><strong>Cơ hội học tập nâng cao bình đẳng</strong>: Các cơ sở giáo dục ở mọi cấp và loại không được thiết lập các điều kiện phân biệt đối xử như tộc, trình độ tu luyện, xuất thân, v.v. trong tuyển sinh, và tiêu chuẩn tuyển sinh phải công khai, minh bạch.</li><li><strong>Đảm bảo giáo dục đặc biệt</strong>: Cung cấp nguồn lực giáo dục đặc biệt thích ứng và hỗ trợ giáo dục từ xa cho các nhóm như sự sống khuyết tật, sự sống tộc khác, sự sống từ位面 xa xôi, v.v.</li><li><strong>Hệ thống cứu trợ giáo dục</strong>: Cung cấp học bổng, học bổng tài năng và khoản vay không lãi suất cho người học gặp khó khăn kinh tế, đảm bảo không mất cơ hội giáo dục vì lý do kinh tế.</li></ol><h2 id="_3-co-cau-he-thong-giao-duc" tabindex="-1">3. Cơ cấu hệ thống giáo dục <a class="header-anchor" href="#_3-co-cau-he-thong-giao-duc" aria-label="Permalink to &quot;3. Cơ cấu hệ thống giáo dục&quot;">​</a></h2><p>Hệ thống giáo dục của văn minh cộng sinh neo được chia thành bốn cấp độ, các cấp độ được kết nối hữu cơ với nhau:</p><table tabindex="0"><thead><tr><th>Cấp độ</th><th>Tên</th><th>Mục tiêu</th><th>Thời gian học</th></tr></thead><tbody><tr><td>Cấp độ thứ nhất</td><td>Giáo dục khởi蒙</td><td>Nuôi dưỡng năng lực nhận thức cơ bản và ý thức cộng sinh, truyền授 pháp môn tu luyện cơ bản</td><td>3-6 năm</td></tr><tr><td>Cấp độ thứ hai</td><td>Giáo dục cơ bản</td><td>Học tập có hệ thống tri thức phổ thông và lý luận tu luyện, khám phá hướng thiên tài của cá nhân</td><td>6-9 năm</td></tr><tr><td>Cấp độ thứ ba</td><td>Giáo dục chuyên môn</td><td>Học tập sâu và thực hành trong hệ thống tu luyện hoặc lĩnh vực chuyên môn đã chọn</td><td>3-10 năm</td></tr><tr><td>Cấp độ thứ tư</td><td>Nghiên cứu cao cấp</td><td>Khám phá tiên phong và nghiên cứu đổi mới dành cho người tu luyện cao cấp và nhà nghiên cứu</td><td>Không giới hạn</td></tr></tbody></table><p>Ngoài ra, &quot;Hệ thống mạng lưới cố vấn&quot; được thành lập: người tu luyện đạt đến một trình độ tu luyện nhất định có nghĩa vụ hướng dẫn người tu luyện sơ cấp trong phạm vi năng lực của mình, và đóng góp hướng dẫn được tính vào lượng đóng góp của cơ chế hợp đồng sản xuất liên hợp, được hưởng phân bổ nguồn lực tương ứng.</p><h2 id="_4-co-so-giao-duc-va-giao-vien" tabindex="-1">4. Cơ sở giáo dục và giáo viên <a class="header-anchor" href="#_4-co-so-giao-duc-va-giao-vien" aria-label="Permalink to &quot;4. Cơ sở giáo dục và giáo viên&quot;">​</a></h2><ul><li><strong>Cơ sở giáo dục công lập</strong>: Do nhà nước hoặc cộng đồng văn minh thành lập, chịu trách nhiệm giáo dục cơ bản miễn phí và dịch vụ giáo dục công cộng, kinh phí được đảm bảo bởi tích lũy công cộng.</li><li><strong>Cơ sở giáo dục tư thục</strong>: Do lực lượng xã hội thành lập theo pháp luật, có thể thu phí hợp lý, nhưng phải接受 sự giám sát của部门主管 giáo dục, và không được quảng cáo giả mạo hoặc thu phí kiểu cướp đoạt.</li><li><strong>Tông môn tu luyện</strong>: Tổ chức tu luyện truyền thống sau khi đăng ký có thể hoạt động như cơ sở giáo dục chuyên môn, phải tuân thủ quy định của luật giáo dục, và không được đóng cửa và độc quyền nguồn lực tu luyện.</li><li><strong>Quyền và nghĩa vụ của giáo viên</strong>: Giáo viên được hưởng các quyền như tự do học thuật, thù lao hợp lý, đào tạo nghề, v.v., đồng thời có nghĩa vụ dạy dỗ, làm gương, bảo vệ quyền riêng tư của học sinh, v.v.</li></ul><h2 id="_5-noi-dung-giao-duc-va-tieu-chuan-chuong-trinh-hoc" tabindex="-1">5. Nội dung giáo dục và tiêu chuẩn chương trình học <a class="header-anchor" href="#_5-noi-dung-giao-duc-va-tieu-chuan-chuong-trinh-hoc" aria-label="Permalink to &quot;5. Nội dung giáo dục và tiêu chuẩn chương trình học&quot;">​</a></h2><p>Nội dung giáo dục phải đáp ứng các yêu cầu sau:</p><ol><li>Bao gồm khái niệm cốt lõi của văn minh cộng sinh và giáo dục phản đối cướp đoạt, nuôi dưỡng ý thức cộng sinh của người học.</li><li>Bao gồm lý luận cơ bản và pháp môn giới thiệu của ba trăm hệ thống tu luyện nguồn gốc.</li><li>Bao gồm tri thức khoa học phổ thông như quy luật vũ trụ, tri thức位面, khoa học sự sống, v.v.</li><li>Bao gồm lịch sử và văn hóa của mọi tộc, thúc đẩy sự hiểu biết và tôn trọng lẫn nhau giữa các tộc.</li><li>Bao gồm环节 tu luyện thực tế và dịch vụ xã hội, nuôi dưỡng năng lực nhất quán tri thức và hành động.</li><li>Cấm truyền bá khái niệm tu luyện kiểu cướp đoạt và tư tưởng phân biệt đối xử.</li></ol><h2 id="_6-trach-nhiem-phap-ly" tabindex="-1">6. Trách nhiệm pháp lý <a class="header-anchor" href="#_6-trach-nhiem-phap-ly" aria-label="Permalink to &quot;6. Trách nhiệm pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ul><li>Từ chối hoặc cản trở sự sống trong độ tuổi đi học nhận giáo dục bắt buộc, ra lệnh khắc phục và xử phạt.</li><li>Cơ sở giáo dục thu phí vi phạm, quảng cáo giả mạo, ra lệnh hoàn trả phí và phạt tiền, trường hợp nghiêm trọng thì thu hồi giấy phép hoạt động giáo dục.</li><li>Giáo viên thể dục hoặc phân biệt đối xử với học sinh,给予 kỷ luật, trường hợp nghiêm trọng thì thu hồi tư cách giáo viên và truy cứu trách nhiệm pháp lý.</li><li>Tư nhân hóa nguồn lực tu luyện công cộng, độc quyền và thu phí, tịch thu thu nhập bất hợp pháp và phạt tiền.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Đảm bảo Giáo dục》 là thực tiễn giáo dục của khái niệm &quot;mọi người đều có con đường&quot; của văn minh cộng sinh neo. Bằng cách đảm bảo quyền được giáo dục, xây dựng hệ thống giáo dục phân cấp, và mở cửa nguồn lực tu luyện, nó đảm bảo mỗi sự sống đều có thể có được con đường tiến hóa phù hợp với bản thân, cung cấp liên tục tri thức và nhân tài cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>37-共生教育体系 (Hệ thống Giáo dục Cộng sinh)</li><li>10-三百套本源修炼体系总览 (Tổng quan Ba trăm Hệ thống Tu luyện Nguồn gốc)</li><li>08-人人有路保障体系 (Hệ thống Đảm bảo Mọi người đều có Con đường)</li></ul>',25)])])}const s=t(g,[["render",u]]);export{m as __pageData,s as default};
